def compare_one(a, b):
    def convert_to_float(x):
        if isinstance(x, str):
            x = x.replace(',', '.')
        return float(x) if not isinstance(x, float) else x

    a, b = convert_to_float(a), convert_to_float(b)

    if a > b:
        return type(a)(a)
    elif a < b:
        return type(b)(b)
    else:
        return None
